SELECT CASE WHEN products.stock_qty >= 391 THEN 'high' WHEN products.stock_qty >= 129 THEN 'mid' ELSE 'low' END stock_qty_bucket, COUNT(DISTINCT store_sales.units) unique_products, MAX(store_sales.sale_date) last_sale_date FROM store_sales INNER JOIN products ON products.id = store_sales.product_id INNER JOIN suppliers ON products.supplier_id = suppliers.id GROUP BY CASE WHEN products.stock_qty >= 391 THEN 'high' WHEN products.stock_qty >= 129 THEN 'mid' ELSE 'low' END;
